import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// Stand-in for a database. Replace with your own data layer.
const posts: Post[] = []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  return posts.slice().reverse()
}

export async function insertPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: String(posts.length + 1),
    title: data.title,
    content: data.content,
    createdAt: new Date().toISOString(),
  }

  posts.push(post)

  return post
}

